const items = $input.all();

// Si Google Sheets devolvió un error (ej. credencial caída o problema de red)
const first = items[0]?.json || {};
if (first.error) {
  const msg = typeof first.error === 'string'
    ? first.error
    : (first.error.message || first.message || 'Google Sheets error');
  return [{
    json: {
      success: false,
      result: null,
      error: {
        type: 'EXTERNAL_SERVICE_ERROR',
        message: msg,
        retryable: true,
      },
    },
  }];
}

let totalDebt = 0;
const contractsFound = [];

for (const item of items) {
  const row = item.json;
  if (!row) continue;

  const rawDebt = row["DEBE"] ?? row["debe"];
  let parsedDebt = 0;
  if (rawDebt !== undefined && rawDebt !== null) {
    const cleanedDebt = String(rawDebt)
      .replace(/[$]/g, '')
      .replace(/\s+/g, '')
      .replace(',', '.');
    const parsed = parseFloat(cleanedDebt);
    if (Number.isFinite(parsed) && parsed > 0) {
      parsedDebt = parsed;
      totalDebt += parsed;
    }
  }

  // Registrar contrato / fila encontrada independientemente del estado
  const code = row["CÓDIGO"] || row["CODIGO"] || row["codigo"] || row["id"] || "";
  const status = row["ESTADO"] || row["estado"] || "";
  if (code || status || rawDebt !== undefined) {
    contractsFound.push({
      code: String(code).trim(),
      status: String(status).trim(),
      debt: Math.round(parsedDebt * 100) / 100,
    });
  }
}

// Redondear a 2 decimales para evitar imprecisiones de coma flotante en JS
const finalDebt = Math.round(totalDebt * 100) / 100;
const hasDebt = finalDebt > 0;

return [
  {
    json: {
      success: true,
      result: {
        hasDebt,
        debt: finalDebt,
        contractsCount: contractsFound.length,
        contracts: contractsFound,
      },
      hasDebt,
      debt: finalDebt,
      error: null,
    },
  },
];

